function extractTokenFromInput(input) {
  const raw = String(input || "").trim();
  if (!raw) return "";
  if (raw.startsWith("http://") || raw.startsWith("https://")) {
    try {
      const url = new URL(raw);
      return url.searchParams.get("token") || "";
    } catch (e) {
    }
  }
  return raw;
}
